async def until(p,predicate,timeout=12):
 end=time.monotonic()+timeout
 while time.monotonic()<end:
  s=await snap(p)
  if predicate(s):return s
  await p.wait_for_timeout(8)
 raise AssertionError('Condition timeout '+str(await snap(p)))
async def fresh(p,d):await d.release();await p.keyboard.press('r');await begin(p,d)
